# Temperature Checker
# Try changing the temperature and see which message appears!

temperature = 22  # Change this value

if temperature > 35:
    message = "It's scorching! Stay hydrated."
elif temperature > 20:
    message = "Nice weather for a walk!"
elif temperature > 10:
    message = "Grab a jacket."
else:
    message = "Stay inside - it's freezing!"

print(f"Temperature: {temperature}°C")
print(f"Advice: {message}")

# What letter grade does a score get?
# Change score and run to see the result.

score = 75

if score >= 90:
    grade = "A"
elif score >= 80:
    grade = "B"
elif score >= 70:
    grade = "C"
elif score >= 60:
    grade = "D"
else:
    grade = "F"

print("Score:", score, "-> Grade:", grade)
